const $=id=>document.getElementById(id),canvas=$("canvas"),ctx=canvas.getContext("2d");
const state={page:"library",assets:{main:[],gift:[]},folders:{main:null,gift:null},preview:null,psd:null,psdMeta:null,canvasW:900,canvasH:900,zones:{main:null,gift:null,mask:null},tool:"select",draft:null,drag:null,combos:[],activeComboId:null,intentDrag:null,intentPanelDrag:null,sunDrag:false};

function init(){bind();addCombo();renderAssets();renderCombos();draw();restoreFolders()}
function bind(){
  document.querySelectorAll(".tab").forEach(b=>b.onclick=()=>showPage(b.dataset.page));
  $("mainInput").onchange=e=>addAssets("main",[...e.target.files]);$("giftInput").onchange=e=>addAssets("gift",[...e.target.files]);
  $("mainFolder").onclick=()=>chooseFolder("main");$("giftFolder").onclick=()=>chooseFolder("gift");
  $("mainRefresh").onclick=()=>refreshFolder("main");$("giftRefresh").onclick=()=>refreshFolder("gift");
  $("previewInput").onchange=e=>setPreview(e.target.files[0]);$("psdInput").onchange=async e=>{state.psd=e.target.files[0]||null;state.psdMeta=state.psd?await readPsdSize(state.psd):null;updatePsdStatus()};
  $("selectTool").onclick=()=>setTool("select");$("rectTool").onclick=()=>setTool("rect");$("polyTool").onclick=()=>setTool("poly");$("clearZones").onclick=()=>{state.zones={main:null,gift:null,mask:null};draw()};
  canvas.onpointerdown=pointerDown;canvas.onpointermove=pointerMove;canvas.onpointerup=pointerUp;canvas.onpointerleave=pointerUp;canvas.ondblclick=finishPolygon;
  $("addCombo").onclick=()=>addCombo();$("exportBtn").onclick=openExport;$("downloadTaskJson").onclick=downloadJson;$("downloadJsx").onclick=downloadJsx;$("writeTask").onclick=writeTask;
  $("excelInput").onchange=e=>handleExcelImport(e.target.files[0]);$("excelReplace").onclick=()=>applyExcelImport("replace");$("excelAppend").onclick=()=>applyExcelImport("append");
  $("resetIntent").onclick=()=>{const c=activeCombo();if(c){pushIntentHistory(c);c.previewLayout=null;renderIntentPreview()}};
  $("intentCanvas").onpointerdown=intentPointerDown;$("intentCanvas").onpointermove=intentPointerMove;$("intentCanvas").onpointerup=intentPointerUp;$("intentCanvas").onpointercancel=intentPointerUp;$("intentCanvas").onpointerleave=()=>{if(!state.intentDrag)$("intentCanvas").style.cursor="default"};
  document.querySelectorAll("[data-align]").forEach(b=>b.onclick=()=>{const c=activeCombo();if(c)pushIntentHistory(c);alignIntentSelection(b.dataset.align)});
  $("rotate45").onclick=()=>rotateIntentSelection(45);
  document.addEventListener("keydown",intentHistoryKeydown);
  bindSunControls();bindShadowPresetControls();
  $("intentResize").onpointerdown=intentPanelResizeStart;document.addEventListener("pointermove",intentPanelResizeMove);document.addEventListener("pointerup",intentPanelResizeEnd);
  const savedIntentWidth=Number(localStorage.getItem("intentPreviewWidth"));if(savedIntentWidth)setIntentPanelWidth(savedIntentWidth);
}
function showPage(page){state.page=page;["library","template","batch"].forEach(p=>$(p+"Page").hidden=p!==page);document.querySelectorAll(".tab").forEach(b=>b.classList.toggle("active",b.dataset.page===page));if(page==="batch")renderCombos();if(page==="template")draw()}
function makeAsset(type,file,source="file",id=crypto.randomUUID()){const asset={id,type,name:file.name,file,source,url:URL.createObjectURL(file),img:null,alphaBounds:null};const img=new Image();img.onload=()=>{asset.img=img;asset.alphaBounds=readAlphaBounds(img);renderIntentPreview()};img.src=asset.url;return asset}
function readAlphaBounds(img){try{const max=700,scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight)),w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale)),cv=document.createElement("canvas");cv.width=w;cv.height=h;const g=cv.getContext("2d",{willReadFrequently:true});g.drawImage(img,0,0,w,h);const d=g.getImageData(0,0,w,h).data;let x0=w,y0=h,x1=-1,y1=-1;for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(d[(y*w+x)*4+3]>8){if(x<x0)x0=x;if(x>x1)x1=x;if(y<y0)y0=y;if(y>y1)y1=y}return x1<0?null:{x:x0/scale,y:y0/scale,w:(x1-x0+1)/scale,h:(y1-y0+1)/scale}}catch(_){return null}}
function addAssets(type,files){const keys=new Set(state.assets[type].map(a=>`${a.name}|${a.file.size}|${a.file.lastModified}`));let count=0;files.forEach(file=>{const key=`${file.name}|${file.size}|${file.lastModified}`;if(keys.has(key))return;state.assets[type].push(makeAsset(type,file));keys.add(key);count++});renderAssets();renderCombos();toast(`已添加 ${count} 个${type==="main"?"主品":"赠品"}`)}
async function chooseFolder(type){if(!window.showDirectoryPicker)return toast("请使用最新版 Chrome 或 Edge 打开网站");try{state.folders[type]=await window.showDirectoryPicker({mode:"read"});await rememberFolder(type,state.folders[type]);await refreshFolder(type)}catch(e){if(e.name!=="AbortError")toast("读取文件夹失败："+e.message)}}
async function refreshFolder(type){const handle=state.folders[type];if(!handle)return;try{if((await handle.requestPermission({mode:"read"}))!=="granted")return toast("没有获得文件夹读取权限");const files=[];for await(const entry of handle.values())if(entry.kind==="file"&&/\.(png|jpe?g|webp)$/i.test(entry.name))files.push(await entry.getFile());files.sort((a,b)=>a.name.localeCompare(b.name,"zh-CN",{numeric:true}));const oldFolder=state.assets[type].filter(a=>a.source==="folder"),manual=state.assets[type].filter(a=>a.source!=="folder"),oldByKey=new Map(oldFolder.map(a=>[`${a.name}|${a.file.size}|${a.file.lastModified}`,a]));const next=files.map(file=>{const key=`${file.name}|${file.size}|${file.lastModified}`,old=oldByKey.get(key);return old||makeAsset(type,file,"folder")});const valid=new Set([...manual,...next].map(a=>a.id));state.assets[type]=[...manual,...next];state.combos.forEach(c=>c[type]=c[type].filter(id=>valid.has(id)));$(type+"FolderName").textContent=`已连接：${handle.name} · ${files.length} 个图片文件`;$(type+"FolderName").classList.add("connected");$(type+"Refresh").disabled=false;renderAssets();renderCombos();toast(`${type==="main"?"主品":"赠品"}文件夹已读取：${files.length} 个素材`)}catch(e){toast("刷新文件夹失败："+e.message)}}
function folderDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open("product-layout-folders",1);req.onupgradeneeded=()=>req.result.createObjectStore("handles");req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function rememberFolder(type,handle){try{const db=await folderDb(),tx=db.transaction("handles","readwrite");tx.objectStore("handles").put(handle,type)}catch(_){}}
async function restoreFolders(){try{const db=await folderDb();for(const type of ["main","gift"]){const handle=await new Promise(resolve=>{const req=db.transaction("handles").objectStore("handles").get(type);req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null)});if(handle){state.folders[type]=handle;$(type+"FolderName").textContent=`已记住：${handle.name} · 点击“刷新文件夹”重新授权并读取`;$(type+"FolderName").classList.add("connected");$(type+"Refresh").disabled=false}}}catch(_){}}
function renderAssets(){["main","gift"].forEach(type=>{const box=$(type+"Assets"),list=state.assets[type];box.innerHTML=list.length?list.map(a=>`<article class="asset"><img src="${a.url}"><div><span title="${a.name}">${a.name}</span><button data-remove="${a.id}" data-type="${type}">×</button></div></article>`).join(""):`<div class="empty">尚未添加${type==="main"?"主品":"赠品"}</div>`});document.querySelectorAll("[data-remove]").forEach(b=>b.onclick=()=>removeAsset(b.dataset.type,b.dataset.remove))}
function removeAsset(type,id){state.assets[type]=state.assets[type].filter(a=>a.id!==id);state.combos.forEach(c=>c[type]=c[type].filter(x=>x!==id));renderAssets();renderCombos()}
function setPreview(file){if(!file)return;state.preview={file,url:URL.createObjectURL(file),img:null};$("previewName").textContent=file.name;const img=new Image();img.onload=()=>{state.preview.img=img;resizeTemplate(img.naturalWidth,img.naturalHeight);draw()};img.src=state.preview.url}
async function readPsdSize(file){try{const b=await file.slice(0,26).arrayBuffer(),v=new DataView(b);if(String.fromCharCode(v.getUint8(0),v.getUint8(1),v.getUint8(2),v.getUint8(3))!=="8BPS")return null;const version=v.getUint16(4,false);if(version!==1&&version!==2)return null;return{width:v.getUint32(18,false),height:v.getUint32(14,false),version}}catch(_){return null}}
function updatePsdStatus(){if(!state.psd)return $("psdName").textContent="未选择";const m=state.psdMeta;if(!m)return $("psdName").textContent=state.psd.name+" · 无法读取尺寸";const same=state.preview?.img&&m.width===state.canvasW&&m.height===state.canvasH,ratioOk=state.preview?.img&&Math.abs(m.width/m.height-state.canvasW/state.canvasH)<.001;$("psdName").textContent=`${state.psd.name} · ${m.width} × ${m.height}px${state.preview?.img?(same?" · 尺寸一致":ratioOk?" · 比例一致，将自动换算":" · 与预览图比例不一致"):""}`}
function resizeTemplate(w,h){const sx=w/state.canvasW,sy=h/state.canvasH;Object.values(state.zones).forEach(z=>{if(!z)return;z.x*=sx;z.y*=sy;z.w*=sx;z.h*=sy;if(z.points)z.points.forEach(p=>{p.x*=sx;p.y*=sy})});state.canvasW=w;state.canvasH=h;canvas.width=w;canvas.height=h;$("sizeLabel").textContent=`${w} × ${h} px`;updatePsdStatus()}
function setTool(tool){if(state.tool==="poly"&&tool!=="poly"&&state.draft)finishPolygon();state.tool=tool;$("selectTool").classList.toggle("active",tool==="select");$("rectTool").classList.toggle("active",tool==="rect");$("polyTool").classList.toggle("active",tool==="poly");$("hint").textContent=tool==="poly"?"依次点击顶点，双击闭合":tool==="rect"?"按住拖动绘制区域":"拖动已有区域调整位置";canvas.style.cursor=tool==="select"?"default":"crosshair";draw()}
function pt(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height}}
function pointerDown(e){const p=pt(e),type=$("drawType").value;if(state.tool==="poly"){if(e.detail>1)return;if(!state.draft)state.draft={type,points:[],hover:p};state.draft.points.push(p);state.draft.hover=p;draw();return}if(state.tool==="rect"){const z={type,x:p.x,y:p.y,w:0,h:0,points:null};state.zones[type]=z;state.drag={kind:"draw",zone:z,start:p};draw();return}const z=hitZone(p);if(z)state.drag={kind:"move",zone:z,start:p,origin:{x:z.x,y:z.y,points:z.points?z.points.map(q=>({...q})):null}}}
function pointerMove(e){const p=pt(e);if(state.tool==="poly"&&state.draft){state.draft.hover=p;draw();return}if(!state.drag)return;const d=state.drag,z=d.zone;if(d.kind==="draw"){z.w=p.x-d.start.x;z.h=p.y-d.start.y}else{const dx=p.x-d.start.x,dy=p.y-d.start.y;z.x=d.origin.x+dx;z.y=d.origin.y+dy;if(z.points)z.points=d.origin.points.map(q=>({x:q.x+dx,y:q.y+dy}))}draw()}
function pointerUp(){if(state.drag?.kind==="draw"){const z=state.drag.zone;if(z.w<0){z.x+=z.w;z.w=-z.w}if(z.h<0){z.y+=z.h;z.h=-z.h}if(z.w<10||z.h<10)state.zones[z.type]=null}state.drag=null;draw()}
function finishPolygon(e){if(e)e.preventDefault();const d=state.draft;if(!d||d.points.length<3){state.draft=null;draw();return}const xs=d.points.map(p=>p.x),ys=d.points.map(p=>p.y);state.zones[d.type]={type:d.type,x:Math.min(...xs),y:Math.min(...ys),w:Math.max(...xs)-Math.min(...xs),h:Math.max(...ys)-Math.min(...ys),points:d.points.map(p=>({...p}))};state.draft=null;setTool("select");toast(`${zoneLabel(d.type)}多边形区域已保存`)}
function pointInPoly(p,pts){let c=false;for(let i=0,j=pts.length-1;i<pts.length;j=i++){const a=pts[i],b=pts[j];if((a.y>p.y)!=(b.y>p.y)&&p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x)c=!c}return c}
function hitZone(p){for(const type of ["mask","gift","main"]){const z=state.zones[type];if(z&&(z.points?pointInPoly(p,z.points):p.x>=z.x&&p.x<=z.x+z.w&&p.y>=z.y&&p.y<=z.y+z.h))return z}return null}
function zoneLabel(type){return type==="main"?"主品排列区域":type==="gift"?"赠品排列区域":"整体产品蒙版"}
function zoneColor(type){return type==="main"?"#e5484d":type==="gift"?"#2f6fed":"#159a68"}
function draw(){ctx.clearRect(0,0,state.canvasW,state.canvasH);ctx.fillStyle="#fff";ctx.fillRect(0,0,state.canvasW,state.canvasH);if(state.preview?.img)ctx.drawImage(state.preview.img,0,0,state.canvasW,state.canvasH);drawZone(state.zones.mask,"#159a68","整体产品蒙版");drawZone(state.zones.main,"#e5484d","主品排列区域");drawZone(state.zones.gift,"#2f6fed","赠品排列区域");drawDraft();renderIntentPreview()}
function drawZone(z,color,label){if(!z)return;ctx.save();ctx.fillStyle=color+"25";ctx.strokeStyle=color;ctx.lineWidth=3;ctx.setLineDash([12,7]);ctx.beginPath();if(z.points){ctx.moveTo(z.points[0].x,z.points[0].y);z.points.slice(1).forEach(p=>ctx.lineTo(p.x,p.y));ctx.closePath()}else ctx.rect(z.x,z.y,z.w,z.h);ctx.fill();ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=color;ctx.font="bold 16px Arial";ctx.fillText(label,z.x+9,z.y+23);ctx.restore()}
function drawDraft(){const d=state.draft;if(!d||!d.points.length)return;const color=zoneColor(d.type);ctx.save();ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=3;ctx.setLineDash([10,6]);ctx.beginPath();ctx.moveTo(d.points[0].x,d.points[0].y);d.points.slice(1).forEach(p=>ctx.lineTo(p.x,p.y));ctx.lineTo(d.hover.x,d.hover.y);ctx.stroke();ctx.setLineDash([]);d.points.forEach(p=>{ctx.beginPath();ctx.arc(p.x,p.y,6,0,Math.PI*2);ctx.fill()});ctx.restore()}

function defaultDropShadow(role){return role==="gift"?{opacity:34,angle:140,distance:9,spread:18,size:8,color:"#000000"}:{opacity:41,angle:140,distance:14,spread:14,size:12,color:"#000000"}}
const SHADOW_PRESETS={sun:{"sun-1":{azimuth:354,elevation:57,opacity:35,softness:35},"sun-2":{azimuth:180,elevation:44,opacity:46,softness:49},"sun-3":{azimuth:131,elevation:66,opacity:46,softness:49},"sun-4":{azimuth:27,elevation:49,opacity:46,softness:49}},giftbox:{"giftbox-1":{linked:true,main:{opacity:67,angle:163,distance:14,spread:29,size:3,color:"#000000"},gift:{opacity:67,angle:163,distance:14,spread:29,size:3,color:"#000000"}},"giftbox-2":{linked:false,main:{opacity:52,angle:0,distance:14,spread:29,size:3,color:"#000000"},gift:{opacity:52,angle:0,distance:14,spread:29,size:3,color:"#000000"}}}};
function defaultSun(){return{mode:"giftbox",enabled:false,azimuth:135,elevation:35,opacity:35,softness:35,contactLift:1.6,corrections:{},giftbox:{linked:false,main:defaultDropShadow("main"),gift:defaultDropShadow("gift")}}}
function ensureSun(c){const old=c.sun||{},legacyEnabled=!!old.enabled;c.sun=Object.assign(defaultSun(),old);if(!old.mode)c.sun.mode=legacyEnabled?"sun":"giftbox";c.sun.enabled=c.sun.mode==="sun";c.sun.corrections=Object.assign({},c.sun.corrections||{});const box=c.sun.giftbox||{};box.linked=!!box.linked;box.main=Object.assign(defaultDropShadow("main"),box.main||{});box.gift=Object.assign(defaultDropShadow("gift"),box.gift||{});c.sun.giftbox=box;return c.sun}
function ensureComboText(c){if(typeof c.needsText!=="boolean")c.needsText=true;c.textContent=Object.assign({headline:"",accent:"",campaign:"",productName:"",purchaseDetail:"",giftDetail:""},c.textContent||{});return c.textContent}
function addCombo(copy){const c=copy?{id:crypto.randomUUID(),name:copy.name+" 副本",main:[...copy.main],gift:[...copy.gift],order:[...(copy.order||[])],previewLayout:copy.previewLayout?JSON.parse(JSON.stringify(copy.previewLayout)):null,sun:JSON.parse(JSON.stringify(ensureSun(copy))),needsText:copy.needsText!==false,textContent:Object.assign({},ensureComboText(copy))}:{id:crypto.randomUUID(),name:`搭配 ${state.combos.length+1}`,main:[],gift:[],order:[],previewLayout:null,sun:defaultSun(),needsText:true,textContent:ensureComboText({})};state.combos.push(c);state.activeComboId=c.id;renderCombos()}
function comboTextPanel(c){const text=ensureComboText(c);return `<div class="combo-text-choice"><label class="text-toggle"><input type="checkbox" data-needs-text ${c.needsText!==false?"checked":""}><span>需要修改文字</span></label><small>${c.needsText!==false?"将修改模板“可变文字”组":"仅生成产品组，不查找或修改文字图层"}</small></div><details class="combo-text-panel" ${c.needsText===false?"hidden":""}><summary>自动文字内容 <span>Excel 导入后仍可在这里修改</span></summary><div class="combo-text-grid">${EXCEL_TEXT_FIELDS.map(field=>{const value=text[field.key]||"",limit=field.key.includes("Detail")?90:field.key==="accent"?18:30,over=[...value].length>limit;return `<label class="combo-text-field ${over?"field-warning":""}"><span>${field.label}<code>${field.layer}</code></span><textarea rows="${field.key.includes("Detail")?2:1}" data-text-key="${field.key}" data-limit="${limit}" placeholder="留空则保留模板原文字">${escapeHtml(value)}</textarea><small>${[...value].length}/${limit}${over?" · 可能超出占位区域":""}</small></label>`}).join("")}</div></details>`}
function bindComboTextPanel(el,c){const text=ensureComboText(c),toggle=el.querySelector("[data-needs-text]");toggle.onchange=()=>{c.needsText=toggle.checked;renderCombos()};el.querySelectorAll("[data-text-key]").forEach(input=>input.oninput=()=>{text[input.dataset.textKey]=input.value;const limit=Number(input.dataset.limit)||0,count=[...input.value].length,field=input.closest(".combo-text-field");field.classList.toggle("field-warning",count>limit);field.querySelector("small").textContent=`${count}/${limit}${count>limit?" · 可能超出占位区域":""}`})}
function instanceKeys(type,ids){const seen={};return ids.map(id=>`${type}:${id}:${seen[id]=(seen[id]||0)+1}`)}
function parseInstanceKey(key){const p=String(key).split(":");return{type:p[0],id:p[1],instance:Math.max(1,Number(p[2])||1)}}
function giftQuantity(c,id){return c.gift.filter(x=>x===id).length}
function ensureComboOrder(c){const valid=[...instanceKeys("main",c.main),...instanceKeys("gift",c.gift)],old=c.order||[],exact=old.filter(k=>valid.includes(k));c.order=exact.concat(valid.filter(k=>!exact.includes(k)))}
