function alignIntentSelection(mode){const c=activeCombo();if(!c)return;const layout=buildIntentLayout(c),items=layout.items.filter(r=>intentSelection(c).includes(r.key));if(!items.length)return toast("请先选择产品剪影");const b=zoneBounds(state.zones.mask||state.zones.main||state.zones.gift);if(mode==="top"){const y=items.length===1?b.y:Math.min(...items.map(r=>r.y));items.forEach(r=>r.y=y)}else if(mode==="bottom"){const y=items.length===1?b.y+b.h:Math.max(...items.map(r=>r.y+r.h));items.forEach(r=>r.y=y-r.h)}else if(mode==="left"){const x=items.length===1?b.x:Math.min(...items.map(r=>r.x));items.forEach(r=>r.x=x)}else if(mode==="right"){const x=items.length===1?b.x+b.w:Math.max(...items.map(r=>r.x+r.w));items.forEach(r=>r.x=x-r.w)}else if(mode==="same-size"){if(items.length<2)return toast("统一大小至少需要选择 2 个剪影");const ref=items.reduce((a,r)=>r.w*r.h>a.w*a.h?r:a),targetH=ref.h;items.forEach(r=>{const ratio=r.w/Math.max(1,r.h),cx=r.x+r.w/2,cy=r.y+r.h/2;r.h=targetH;r.w=targetH*ratio;r.x=cx-r.w/2;r.y=cy-r.h/2;constrainIntentItem(r,b)})}else if(mode==="largest"){if(items.length<2)return toast("对齐最大项至少需要选择 2 个剪影");const ref=items.reduce((a,r)=>r.w*r.h>a.w*a.h?r:a),bottom=ref.y+ref.h;items.forEach(r=>{r.y=bottom-r.h;constrainIntentItem(r,b)})}else if(mode==="space-x"&&items.length>2){items.sort((a,z)=>a.x-z.x);const first=items[0].x,last=items[items.length-1].x+items[items.length-1].w,total=items.reduce((s,r)=>s+r.w,0),gap=(last-first-total)/(items.length-1);let x=first;items.forEach(r=>{r.x=x;x+=r.w+gap})}else if(mode==="space-y"&&items.length>2){items.sort((a,z)=>a.y-z.y);const first=items[0].y,last=items[items.length-1].y+items[items.length-1].h,total=items.reduce((s,r)=>s+r.h,0),gap=(last-first-total)/(items.length-1);let y=first;items.forEach(r=>{r.y=y;y+=r.h+gap})}else if(mode.indexOf("space-")===0)return toast("等距排列至少需要选择 3 个剪影");layout.manual=true;renderIntentPreview()}
