function intentPanelResizeStart(e){const current=$("intentPreview");state.intentPanelDrag={startX:e.clientX,startWidth:current?current.getBoundingClientRect().width:330};e.currentTarget.setPointerCapture(e.pointerId);e.preventDefault()}
function intentPanelResizeMove(e){const d=state.intentPanelDrag;if(!d)return;setIntentPanelWidth(d.startWidth+e.clientX-d.startX)}
function intentPanelResizeEnd(){if(!state.intentPanelDrag)return;const width=parseFloat(getComputedStyle($("batchPage")).getPropertyValue("--intent-width"))||330;localStorage.setItem("intentPreviewWidth",String(width));state.intentPanelDrag=null}
function picker(c,type,title){const list=state.assets[type],unique=new Set(c[type]).size;return `<section class="picker"><h3>${title} · 已选 ${unique}${type==="gift"?` 种 / 共 ${c.gift.length} 件`:""}</h3><div class="picker-grid">${list.length?list.map(a=>{const selected=c[type].includes(a.id),q=type==="gift"?giftQuantity(c,a.id):1;return `<label class="pick ${selected?"selected":""}" data-type="${type}" data-asset="${a.id}"><input type="checkbox" ${selected?"checked":""}><img src="${a.url}"><span title="${a.name}">${a.name}</span>${type==="gift"&&selected?`<span class="qty-control"><button type="button" class="qty-minus" data-asset="${a.id}" ${q<=1?"disabled":""}>−</button><b>${q}</b><button type="button" class="qty-plus" data-asset="${a.id}" ${q>=20?"disabled":""}>＋</button></span>`:""}</label>`}).join(""):`<div class="empty">请先在素材库添加${type==="main"?"主品":"赠品"}</div>`}</div></section>`}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]))}

function zoneData(type){const z=state.zones[type];if(!z)return null;const points=z.points||[{x:z.x,y:z.y},{x:z.x+z.w,y:z.y},{x:z.x+z.w,y:z.y+z.h},{x:z.x,y:z.y+z.h}];const data={type,points:points.map(p=>({x:p.x/state.canvasW,y:p.y/state.canvasH}))};if(type!=="mask"){data.padding=Number($(type+"Padding").value)||0;data.gapRatio=(Number($(type+"Gap").value)||0)/100;data.layout=type==="main"?$("mainLayout").value:"height";data.stackSmall=type==="gift"?$("giftStack").checked:false}return data}
function comboTextTask(c){if(c.needsText===false)return[];const values=ensureComboText(c);return EXCEL_TEXT_FIELDS.map(field=>({key:field.key,label:field.label,layer:field.layer,value:String(values[field.key]||"")})).filter(item=>item.value)}
function taskData(){
  const used=new Set;state.combos.forEach(c=>[...c.main,...c.gift].forEach(id=>used.add(id)));
  return{version:23,taskName:$("taskName").value,template:{name:$("templateName").value,psd:state.psd?.name||null,preview:state.preview?.file.name||null,width:state.canvasW,height:state.canvasH,psdWidth:state.psdMeta?.width||null,psdHeight:state.psdMeta?.height||null},variableTextLayers:EXCEL_TEXT_FIELDS.map(field=>field.layer),zones:{main:zoneData("main"),gift:zoneData("gift"),mask:zoneData("mask")},layout:{mode:"mainFirstFillGifts",density:"maximum",mainPriority:true,tallRatio:2,lockTallMains:true,tallEdgeFit:true,giftStack:"priority",hardBoundary:true,shadowSafe:false,globalInflate:true,manualOrder:true,priorityAnchor:true,coreGiftRatio:1.5},artboards:{columns:Number($("artboardColumns").value)||4,gap:Number($("artboardGap").value)||100},combinations:state.combos.map((c,i)=>{ensureComboOrder(c);const preview=buildIntentLayout(c),sun=ensureSun(c);return{index:i+1,name:c.name,needsText:c.needsText!==false,text:comboTextTask(c),sun:{mode:sun.mode,enabled:sun.mode==="sun",baked:true,azimuth:Number(sun.azimuth),elevation:Number(sun.elevation),opacity:Number(sun.opacity),softness:Number(sun.softness),contactLift:Number(sun.contactLift),giftbox:JSON.parse(JSON.stringify(sun.giftbox)),corrections:c.order.map(key=>{const p=parseInstanceKey(key);return{type:p.type,path:assetPath(p.type,p.id),instance:p.instance,factor:(Number(sun.corrections[key])||100)/100}})},main:c.main.map(id=>assetPath("main",id)),gift:c.gift.map(id=>assetPath("gift",id)),order:c.order.map(key=>{const p=parseInstanceKey(key);return{type:p.type,path:assetPath(p.type,p.id),instance:p.instance}}),intentLayout:preview.items.map((r,n)=>{const p=parseInstanceKey(r.key),base=`shadows/${String(i+1).padStart(2,"0")}/${String(n+1).padStart(3,"0")}`;return{type:p.type,path:assetPath(p.type,p.id),instance:p.instance,x:r.x/state.canvasW,y:r.y/state.canvasH,w:r.w/state.canvasW,h:r.h/state.canvasH,rotation:intentAngle(r),shadow:sun.enabled?base+"_sun.png":null,contactShadow:sun.enabled?base+"_contact.png":null}})}}),usedAssets:[...used]}
}
function assetExportName(a){return `${a.id}__${safe(a.file.name)}`}
function assetPath(type,id){const a=state.assets[type].find(x=>x.id===id);return a?`products/${type}/${assetExportName(a)}`:null}
function validate(){const errors=[];if(!state.psd)errors.push("未选择 PSD 模板");if(!state.preview)errors.push("未选择模板预览图");if(state.psd&&!state.psdMeta)errors.push("无法读取 PSD/PSB 的实际尺寸");if(state.psdMeta&&state.preview&&Math.abs(state.psdMeta.width/state.psdMeta.height-state.canvasW/state.canvasH)>=.001)errors.push(`PSD 实际比例 ${state.psdMeta.width}×${state.psdMeta.height} 与预览图 ${state.canvasW}×${state.canvasH} 不一致`);if(!state.zones.main)errors.push("未绘制主品排列区域");if(!state.zones.gift)errors.push("未绘制赠品排列区域");if(!state.zones.mask)errors.push("未绘制整体产品蒙版");state.combos.forEach((c,i)=>{if(!c.main.length)errors.push(`组合 ${i+1} 没有选择主品`)});return errors}
function openExport(){const errors=validate(),box=$("exportCheck");box.className="export-check "+(errors.length?"bad":"ok");box.innerHTML=errors.length?`<strong>暂时不能导出</strong><br>${errors.join("<br>")}`:`<strong>任务检查通过</strong><br>${state.combos.length} 个组合将生成 ${state.combos.length} 个画板，尺寸均为 ${state.canvasW} × ${state.canvasH} px`;$("writeTask").disabled=errors.length>0;$("exportDialog").showModal()}
function download(name,data,type="text/plain;charset=utf-8"){const a=document.createElement("a"),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function downloadJson(){download("task.json",JSON.stringify(taskData(),null,2),"application/json")}
function downloadJsx(){download("运行本任务.jsx",generateBatchPhotoshopRunner())}
async function writeFile(dir,name,data){const h=await dir.getFileHandle(name,{create:true}),w=await h.createWritable();await w.write(data);await w.close()}
async function writeTask(){if(!window.showDirectoryPicker)return toast("请使用最新版 Chrome 或 Edge");try{const root=await window.showDirectoryPicker({mode:"readwrite"}),folder=await root.getDirectoryHandle(safe($("taskName").value),{create:true}),data=taskData();await writeFile(folder,"task.json",JSON.stringify(data,null,2));await writeFile(folder,"运行本任务.jsx",generateBatchPhotoshopRunner());const template=await folder.getDirectoryHandle("template",{create:true});await writeFile(template,state.psd.name,state.psd);await writeFile(template,state.preview.file.name,state.preview.file);const products=await folder.getDirectoryHandle("products",{create:true});for(const type of ["main","gift"]){const dir=await products.getDirectoryHandle(type,{create:true});const ids=new Set(state.combos.flatMap(c=>c[type]));for(const a of state.assets[type].filter(x=>ids.has(x.id)))await writeFile(dir,assetExportName(a),a.file)}const shadowRoot=await folder.getDirectoryHandle("shadows",{create:true});for(let i=0;i<state.combos.length;i++){const c=state.combos[i],sun=ensureSun(c);if(!sun.enabled)continue;const dir=await shadowRoot.getDirectoryHandle(String(i+1).padStart(2,"0"),{create:true}),layout=buildIntentLayout(c);for(let n=0;n<layout.items.length;n++){const projection=sunShadowCanvas(c,layout.items[n],state.canvasW,state.canvasH,"#000000"),contact=contactShadowCanvas(c,layout.items[n],state.canvasW,state.canvasH,"#000000"),spec=data.combinations[i].intentLayout[n],stem=String(n+1).padStart(3,"0");spec.shadowBounds=canvasAlphaBounds(projection);spec.contactShadowBounds=canvasAlphaBounds(contact);await writeFile(dir,stem+"_sun.png",await canvasBlob(projection));await writeFile(dir,stem+"_contact.png",await canvasBlob(contact))}}await writeFile(folder,"task.json",JSON.stringify(data,null,2));await folder.getDirectoryHandle("output",{create:true});$("exportDialog").close();toast("完整多画板任务已导出（太阳投影与接触阴影已分层）") }catch(e){if(e.name!=="AbortError")toast("导出失败："+e.message)}}
function safe(s){return String(s||"批量商品图任务").replace(/[\\/:*?"<>|]/g,"_")}
function toast(s){const t=$("toast");t.textContent=s;t.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove("show"),2400)}
init();
